const checkPhone = (rule, value, callback) => {
  if (value === '') {
    callback()
  }
  if (/^[1-9][0-9]{7,12}$/.test(value) || value === undefined) {
    callback()
  } else {
    const span = <span><IntlMessages id='Jumlah karakter' />&nbsp;7 - 12</span>
    callback(span)
  }
}

