const checkDob = (rule, value, callback) => {
  const date = new Date()
  const spt = moment(value).format('YYYY-MM-DD').split('-')[0]
  const sptCurrent = moment(date).format('YYYY-MM-DD').split('-')[0]
  const sptmCurrent = moment(date).format('YYYY-MM-DD').split('-')[1]
  const sptm = moment(value).format('YYYY-MM-DD').split('-')[1]
  // const sptd = moment(value).format('YYYY-MM-DD').split('-')[2]
  // const sptdCurrent = moment(date).format('YYYY-MM-DD').split('-')[1]
  const error = <IntlMessages id='Usia harus antara 17-60 tahun' />
  if (value && ((sptCurrent - spt) < 16 || ((sptCurrent - spt) > 60))) {
    callback(error)
  }
  if (value && ((sptCurrent - spt) === 16)) {
    if ((sptmCurrent - sptm) < 6) {
      callback(error)
    }
    callback()
  }
  callback()
}

// requirement is the date should be greater than 1 year old
const checkDobShopee = (rule, value, callback) => {
  let selectDate = moment(value)
  const years = moment().diff(selectDate, 'years')
  const error = <IntlMessages id='Usia harus parutan dari satu tahun' />
  if (years<1) {
    callback(error)
  }
  callback()
}

