const checkDobOneYearAndAboveSendo = (rule, value, callback) => {
  const date = new Date()
  const spt = moment(value).format('YYYY-MM-DD').split('-')[0]
  const sptCurrent = moment(date).format('YYYY-MM-DD').split('-')[0]
  const sptmCurrent = moment(date).format('YYYY-MM-DD').split('-')[1]
  const sptd = moment(value).format('YYYY-MM-DD').split('-')[2]
  const sptdCurrent = moment(date).format('YYYY-MM-DD').split('-')[2]
  const sptm = moment(value).format('YYYY-MM-DD').split('-')[1]
  const error = <IntlMessages id='Usia harus antara 1-69 tahun' />
  if (value && ((sptCurrent - spt) < 1 || ((sptCurrent - spt) > 69))) {
    callback(error)
  }
  if (value && ((sptCurrent - spt) === 1)) {
    if (((sptmCurrent - sptm) < 0) || (((sptmCurrent - sptm) === 0) && ((sptd - sptdCurrent) > 0))) {
      callback(error)
    }
    callback()
  }
  callback()
}
