import React, { Component } from 'react'
import PropTypes from 'prop-types'
import { connect } from 'react-redux'
import { injectIntl } from 'react-intl'
import { GosureCoronaStyle, GosureCoronaFormStyle } from './index.style'
import endorseActions from '../../../../../redux/Endorsement/actions'
import EndorseWelcome from '../EndorseWelcome'
import IntlMessages from '../../../../../components/utility/intlMessages'
import CircularLoader from '../../../../../components/CircularLoader'
import { Form, Row, Col, Button, notification } from 'antd'
import { ContainerTitle, ContainerSubTitle } from '../../../GosureEndorsement/componets/GosureEndorseContainer/index.style'
import { ENDORSE_LANG } from '../../../constants'
import { getFormItems } from '../../../../../components/utility/formItems'
import { LANG_STRINGS } from '../../../../../constants/lang'
import validator from '../../../../../helpers/validator'

const {
  submitGosureEndorseForm, resetGosureEndorseRedux
} = endorseActions

class GosureCoronaForm extends Component {
  static propTypes = {
    id: PropTypes.string
  }

  componentWillReceiveProps (nextProps) {
    const { submitEndorseError, gosureDetailsMessage } = nextProps
    if (submitEndorseError && gosureDetailsMessage && (gosureDetailsMessage !== 'success')) {
      notification['error']({
        message: this.intlText({ id: 'Error' }),
        description: this.intlText({ id: gosureDetailsMessage })
      })
      // this is clear the error messsage if any left after popup show
      this.props.resetGosureEndorseRedux(['gosureDetailsMessage'])
    }
  }

  intlText = (messageObj = { id: ' ' }) => {
    return this.props.intl.formatMessage(messageObj)
  }

  handleFormSubmit = async (e) => {
    e.preventDefault()
    const { form } = this.props
    const valid = await this.validateForm()
    if (!valid) {
      return
    }
    const formBody = form.getFieldsValue()
    // the form contains the same field as a name
    // as required in request body
    const body = {
      ...formBody,
      dob: formBody.dob.format('YYYY-MM-DD')
    }
    this.props.submitGosureEndorseForm({
      body,
      id: this.props.id
    })
  }

  async validateForm () {
    return new Promise((resolve) => {
      this.props.form.validateFields((error) => {
        resolve(!error)
      })
    })
  }

  render () {
    const {
      submitEndorseLoading, gosureDetailsMessage
    } = this.props
    const isSuccessFulEndorse = gosureDetailsMessage === 'success'

    return (
      <GosureCoronaStyle>
        {
          isSuccessFulEndorse ? <EndorseWelcome /> : (
            <CircularLoader isSpining={submitEndorseLoading}>
              <GosureCoronaFormStyle>
                <Form onSubmit={this.handleFormSubmit}>
                  <ContainerTitle>
                    <IntlMessages id={ENDORSE_LANG.activeYourGosurePolicy} />
                  </ContainerTitle>
                  <ContainerSubTitle>
                    <IntlMessages id={ENDORSE_LANG.pleaseFillFormForKTPAndDob} />
                  </ContainerSubTitle>
                  <Row gutter={{ xs: 8, sm: 16, md: 10, lg: 10 }}>
                    <Col xs={24} sm={24} md={8} lg={8}>
                      {
                        getFormItems.call(this, {
                          formName: 'ktp',
                          type: 'alphanumeric',
                          label: LANG_STRINGS.ktpNumber,
                          placeHolder: LANG_STRINGS.ktpNumber,
                          initialValue: '',
                          required: true,
                          validator: validator.validateIdentityKtp
                        })
                      }
                    </Col>
                    <Col xs={24} sm={24} md={8} lg={8}>
                      {
                        getFormItems.call(this, {
                          formName: 'dob',
                          type: 'dob',
                          label: LANG_STRINGS.dateOfBirth,
                          placeHolder: LANG_STRINGS.dateOfBirth,
                          initialValue: '',
                          required: true,
                          validator: validator.checkDobCorona
                        })
                      }
                    </Col>
                  </Row>
                  <div className='form-submit-btn'>
                    <Button
                      type='primary'
                      className='form-btn'
                      htmlType='submit'
                      key='submit'
                    >
                      <IntlMessages id={LANG_STRINGS.submit} />
                    </Button>
                  </div>
                </Form>
              </GosureCoronaFormStyle>
            </CircularLoader>
          )
        }
      </GosureCoronaStyle>
    )
  }
}

const GosureCoronaFormWrapped = Form.create()(GosureCoronaForm)
export default connect(
  state => ({
    gosureDetailsMessage: state.Endorsement.gosureDetailsMessage,
    submitEndorseLoading: state.Loading.SUBMIT_GOSURE_ENDORSE,
    submitEndorseError: state.Error.SUBMIT_GOSURE_ENDORSE
  }),
  {
    resetGosureEndorseRedux,
    submitGosureEndorseForm
  }
)(injectIntl(GosureCoronaFormWrapped))
